import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type TypewriterProps = Record<string, any>;

const Typewriter: React.FC<TypewriterProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  showGlow = true,
  glowColor = "#0066ff",
  glowOpacity = 0.3,
  durationInSeconds = 8,
  text = "Welcome to Malloy Studio.\nCrafting stories through motion.",
  textColor = "#ffffff",
  fontSize = 80,
  typingSpeed = 2,
  startDelayFrames = 30,
  cursorBlinkRate = 15,
  showCursor = true,
  cursorColor = "#ffffff",
}) => {

  {/* Load Google Fonts */ }
  useFontLoader(["Poppins"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { width, height, durationInFrames, fps } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Logic
  const framesPassed = Math.max(0, frame - startDelayFrames);
  const charsToReveal = Math.floor(framesPassed / typingSpeed);
  const displayedText = text.slice(0, Math.max(0, charsToReveal));
  
  const isTypingFinished = charsToReveal >= text.length;
  // Cursor stays solid while actively typing, blinks when idle
  const isActivelyTyping = framesPassed > 0 && !isTypingFinished;
  const cursorOpacity = (!isActivelyTyping && Math.floor(frame / cursorBlinkRate) % 2 === 0) ? 0 : 1;

  // Exit Wipe Animation (Right to Left sweep, clipping the text out)
  const wipeStartFrame = durationInFrames - fps;
  const wipeProgress = interpolate(
    frame,
    [wipeStartFrame, durationInFrames],
    [0, 100],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.inOut(Easing.ease),
    }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Poppins" }}>
      
      {/* Background Glow */}
      {showGlow && (
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            background: `radial-gradient(circle at bottom, ${glowColor} 0%, transparent 60%)`,
            opacity: glowOpacity,
            pointerEvents: "none",
            zIndex: 0,
          }}
        />
      )}

      {/* Main Content */}
      <div 
        style={{ 
          position: "relative",
          zIndex: 1,
          display: "flex", 
          flexDirection: "column", 
          justifyContent: "center", 
          alignItems: "center", 
          width: "100%", 
          height: "100%",
          padding: `${width * 0.05}px`
        }}
      >
        <div 
          style={{ 
            maxWidth: width * 0.8,
            textAlign: "center",
            fontSize: `${fontSize}px`,
            color: textColor,
            lineHeight: 1.4,
            whiteSpace: "pre-wrap",
            wordBreak: "break-word",
            fontWeight: 400,
            clipPath: `inset(0 ${wipeProgress}% 0 0)`, // Wipes text off to the left by encroaching from the right
            transition: "none",
          }}
        >
          {displayedText}
          {showCursor && (
            <span
              style={{
                display: "inline-block",
                width: `${fontSize * 0.08}px`,
                height: `${fontSize * 0.9}px`,
                backgroundColor: cursorColor,
                marginLeft: "4px",
                verticalAlign: "baseline",
                position: "relative",
                top: `${fontSize * 0.1}px`,
                opacity: cursorOpacity,
                transition: "none",
              }}
            />
          )}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default Typewriter;